DROP TABLE QSTEST/QRES01;
CREATE TABLE QSTEST/QRES01 (C1, C2, C3, C4, C5, C6, C7) AS (SELECT CUSNO, NAME, STATUS, BAL, SINCE, CREDIT, NOTE FROM QSTEST/CUSTOMER) WITH NO DATA;
INSERT INTO QSTEST/QRES01 SELECT CUSNO, NAME, STATUS, BAL, SINCE, CREDIT, NOTE FROM QSTEST/CUSTOMER ORDER BY CUSNO;
DROP TABLE QSTEST/QRES02;
CREATE TABLE QSTEST/QRES02 (C1, C2, C3) AS (SELECT C.NAME, COUNT(*), SUM(O.AMOUNT) FROM QSTEST/CUSTOMER C JOIN QSTEST/ORDERS O ON C.CUSNO = O.CUSNO GROUP BY C.NAME) WITH NO DATA;
INSERT INTO QSTEST/QRES02 SELECT C.NAME, COUNT(*), SUM(O.AMOUNT) FROM QSTEST/CUSTOMER C JOIN QSTEST/ORDERS O ON C.CUSNO = O.CUSNO GROUP BY C.NAME ORDER BY C.NAME;
DROP TABLE QSTEST/QRES03;
CREATE TABLE QSTEST/QRES03 (C1, C2) AS (SELECT C.CUSNO, C.NAME FROM QSTEST/CUSTOMER C LEFT JOIN QSTEST/ORDERS O ON C.CUSNO = O.CUSNO WHERE O.ORDNO IS NULL) WITH NO DATA;
INSERT INTO QSTEST/QRES03 SELECT C.CUSNO, C.NAME FROM QSTEST/CUSTOMER C LEFT JOIN QSTEST/ORDERS O ON C.CUSNO = O.CUSNO WHERE O.ORDNO IS NULL ORDER BY C.CUSNO;
DROP TABLE QSTEST/QRES04;
CREATE TABLE QSTEST/QRES04 (C1, C2) AS (SELECT ORDNO, AMOUNT FROM QSTEST/ORDERS WHERE AMOUNT BETWEEN 50 AND 500) WITH NO DATA;
INSERT INTO QSTEST/QRES04 SELECT ORDNO, AMOUNT FROM QSTEST/ORDERS WHERE AMOUNT BETWEEN 50 AND 500 ORDER BY AMOUNT DESC, ORDNO;
DROP TABLE QSTEST/QRES05;
CREATE TABLE QSTEST/QRES05 (C1, C2) AS (SELECT L.PRODID, SUM(L.QTY * L.PRICE) FROM QSTEST/ORDLINE L GROUP BY L.PRODID HAVING SUM(L.QTY * L.PRICE) > 20) WITH NO DATA;
INSERT INTO QSTEST/QRES05 SELECT L.PRODID, SUM(L.QTY * L.PRICE) FROM QSTEST/ORDLINE L GROUP BY L.PRODID HAVING SUM(L.QTY * L.PRICE) > 20 ORDER BY 2 DESC;
DROP TABLE QSTEST/QRES06;
CREATE TABLE QSTEST/QRES06 (C1) AS (SELECT NAME FROM QSTEST/CUSTOMER WHERE NAME LIKE '%a%' AND STATUS = 'A') WITH NO DATA;
INSERT INTO QSTEST/QRES06 SELECT NAME FROM QSTEST/CUSTOMER WHERE NAME LIKE '%a%' AND STATUS = 'A' ORDER BY NAME;
DROP TABLE QSTEST/QRES07;
CREATE TABLE QSTEST/QRES07 (C1, C2, C3, C4) AS (SELECT CUSNO, COALESCE(NOTE, 'none'), LENGTH(TRIM(NAME)), SUBSTR(NAME, 1, 2) FROM QSTEST/CUSTOMER WHERE SINCE IS NOT NULL) WITH NO DATA;
INSERT INTO QSTEST/QRES07 SELECT CUSNO, COALESCE(NOTE, 'none'), LENGTH(TRIM(NAME)), SUBSTR(NAME, 1, 2) FROM QSTEST/CUSTOMER WHERE SINCE IS NOT NULL ORDER BY CUSNO;
DROP TABLE QSTEST/QRES08;
CREATE TABLE QSTEST/QRES08 (C1, C2, C3, C4, C5, C6, C7) AS (SELECT EVTID, DMDY, DJUL, DUSA, TUSA, DAYS(DJIS) - DAYS(DATE '2000-01-01'), DAYOFWEEK(DEUR) FROM QSTEST/EVENTS) WITH NO DATA;
INSERT INTO QSTEST/QRES08 SELECT EVTID, DMDY, DJUL, DUSA, TUSA, DAYS(DJIS) - DAYS(DATE '2000-01-01'), DAYOFWEEK(DEUR) FROM QSTEST/EVENTS ORDER BY EVTID;
DROP TABLE QSTEST/QRES09;
CREATE TABLE QSTEST/QRES09 (C1, C2, C3, C4, C5, C6, C7, C8, C9) AS (SELECT TID, FA, FS, FP, FB, FB18, FL, FT, FZ FROM QSTEST/TYPES) WITH NO DATA;
INSERT INTO QSTEST/QRES09 SELECT TID, FA, FS, FP, FB, FB18, FL, FT, FZ FROM QSTEST/TYPES ORDER BY TID;
DROP TABLE QSTEST/QRES10;
CREATE TABLE QSTEST/QRES10 (C1, C2, C3, C4) AS (SELECT ORDNO, CUSNO, NAME, AMOUNT FROM QSTEST/ORDJOIN) WITH NO DATA;
INSERT INTO QSTEST/QRES10 SELECT ORDNO, CUSNO, NAME, AMOUNT FROM QSTEST/ORDJOIN ORDER BY ORDNO;
DROP TABLE QSTEST/QRES11;
CREATE TABLE QSTEST/QRES11 (C1, C2) AS (SELECT CUSNO, NAME FROM QSTEST/CUSTOMER WHERE CUSNO IN (SELECT CUSNO FROM QSTEST/ORDERS WHERE AMOUNT > 100)) WITH NO DATA;
INSERT INTO QSTEST/QRES11 SELECT CUSNO, NAME FROM QSTEST/CUSTOMER WHERE CUSNO IN (SELECT CUSNO FROM QSTEST/ORDERS WHERE AMOUNT > 100) ORDER BY CUSNO;
DROP TABLE QSTEST/QRES12;
CREATE TABLE QSTEST/QRES12 (C1, C2) AS (SELECT PRODID, SUM(ONHAND) FROM QSTEST/INVENTORY GROUP BY PRODID) WITH NO DATA;
INSERT INTO QSTEST/QRES12 SELECT PRODID, SUM(ONHAND) FROM QSTEST/INVENTORY GROUP BY PRODID ORDER BY PRODID;
